      SUBROUTINE THREAD(NM,COR)CC     ADVANCE BEAM CENTROIDCC ----------------------------------------------------------------------      INCLUDE 'ELM17A.CIN'      INCLUDE 'R.CIN'      INCLUDE 'T.CIN'      INCLUDE 'U.CIN'C ----------------------------------------------------------------------      INTEGER          J, NM      REAL             COO(6), COR(6), COT(6)CC     FIRST ORDER TERMSC      DO 10 J = 1, 6   10 COO(J) = COR(J)      IF (NM .EQ. 0) THEN        CALL THRED1(R,COR)      ELSE        CALL THRED1(RV,COR)      ENDIFCC     SECOND-ORDER TERMSC      IF (NORD1 .LE. 1) GO TO 100      DO 60 J = 1, 6      COT(J) = COR(J)   60 COR(J) = COO(J)      IF (NM .EQ. 0) THEN        CALL THRED2(T,COR)      ELSE        CALL THRED2(TV,COR)      ENDIFC      DO 70 J = 1, 6   70 COR(J) = COR(J) + COT(J)CC     THIRD-ORDER TERMSC      IF (NORD1 .LE. 2) GO TO 100      DO 80 J = 1, 6      COT(J) = COR(J)   80 COR(J) = COO(J)      IF (NM .EQ. 0) THEN        CALL THRED3(U,COR)      ELSE        CALL THRED3(UV,COR)      ENDIFC      DO 90 J = 1, 6   90 COR(J) = COR(J) + COT(J)C  100 RETURN      END